using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using Staybnb.Data;using Staybnb.Models;using Staybnb.Services;
namespace Staybnb.Controllers;
[Authorize] public class CommunicationController(ApplicationDbContext db,UserManager<ApplicationUser> users,ActivityLogger logger):Controller {
 public async Task<IActionResult> Inbox(){var uid=users.GetUserId(User);var messages=await db.Messages.Include(m=>m.Sender).Include(m=>m.Recipient).Where(m=>m.RecipientId==uid||m.SenderId==uid).OrderByDescending(m=>m.SentAt).ToListAsync();foreach(var m in messages.Where(m=>m.RecipientId==uid&&!m.IsRead))m.IsRead=true;await db.SaveChangesAsync();return View(messages);}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Send(string recipientEmail,string body){if(string.IsNullOrWhiteSpace(body)||body.Length>2000){TempData["Error"]="Message is required and must be under 2,000 characters.";return RedirectToAction(nameof(Inbox));}var recipient=await users.FindByEmailAsync(recipientEmail);if(recipient==null){TempData["Error"]="Recipient email not found.";return RedirectToAction(nameof(Inbox));}var uid=users.GetUserId(User)!;if(recipient.Id==uid){TempData["Error"]="You cannot message yourself.";return RedirectToAction(nameof(Inbox));}db.Messages.Add(new Message{SenderId=uid,RecipientId=recipient.Id,Body=body.Trim()});db.Notifications.Add(new Notification{UserId=recipient.Id,Title="New message",Body=$"You have a new message from {User.Identity?.Name}.",Link="/Communication/Inbox"});await db.SaveChangesAsync();await logger.LogAsync(uid,"MessageSent",$"Message sent to {recipient.Email}.","Message");return RedirectToAction(nameof(Inbox));}
 public async Task<IActionResult> Notifications(){var uid=users.GetUserId(User);var items=await db.Notifications.Where(n=>n.UserId==uid).OrderByDescending(n=>n.CreatedAt).ToListAsync();foreach(var n in items)n.IsRead=true;await db.SaveChangesAsync();return View(items);}
}